const f = $('Leave Request Form').first().json;
const cfg = $('Settings').first().json;
const emp = String(f['Employee ID'] || '').trim().toUpperCase();
const date = String(f['Leave Date'] || '').slice(0, 10);
const month = date.slice(0, 7);
const dayType = f['Leave Type'] === 'Half Day' ? 'Half Day' : 'Full Day';
const days = dayType === 'Half Day' ? 0.5 : 1;
const limit = Number(cfg.monthly_limit) || 3;
const rows = $input.all().map(i => i.json).filter(r => r && r.request_id);
const sameMonth = rows.filter(r => String(r.leave_date || '').slice(0, 7) === month);
const isApproved = st => String(st || '').indexOf('Approved') === 0;
const used = sameMonth.filter(r => isApproved(r.status)).reduce((s, r) => s + (Number(r.leave_days) || 0), 0);
const escalated = used + days > limit;
const hist = sameMonth.slice().sort((a, b) => String(a.leave_date).localeCompare(String(b.leave_date)));
const cell = 'padding:6px 8px;border-bottom:1px solid #eef0f3;font-size:13px;text-align:left';
const color = st => isApproved(st) ? '#15803d' : (String(st).indexOf('Rejected') >= 0 ? '#b91c1c' : '#b45309');
let historyHtml = '<p style="color:#6b7280;font-size:13px;margin:4px 0">No other leave requests this month.</p>';
if (hist.length > 0) {
  historyHtml = '<table style="width:100%;border-collapse:collapse;margin:6px 0"><tr style="background:#f3f4f6"><th style="' + cell + '">Date</th><th style="' + cell + '">Type</th><th style="' + cell + '">Days</th><th style="' + cell + '">Status</th></tr>'
    + hist.map(r => '<tr><td style="' + cell + '">' + r.leave_date + '</td><td style="' + cell + '">' + r.day_type + '</td><td style="' + cell + '">' + r.leave_days + '</td><td style="' + cell + ';color:' + color(r.status) + ';font-weight:bold">' + r.status + '</td></tr>').join('')
    + '</table>';
}
return [{ json: {
  request_id: 'LR-' + Date.now(),
  employee_id: emp,
  employee_name: String(f['Employee Name'] || '').trim(),
  employee_email: String(f['Email'] || '').trim(),
  leave_date: date,
  month: month,
  day_type: dayType,
  leave_days: days,
  reason: String(f['Reason'] || ''),
  leaves_used_before: used,
  monthly_limit: limit,
  escalated: escalated,
  status: escalated ? 'Pending HR + Director' : 'Pending HR',
  submitted_at: $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm'),
  hr_email: cfg.hr_email,
  director_email: cfg.director_email,
  remaining_days: Math.max(limit - used, 0),
  history_html: historyHtml,
} }];

const limit = Number($('Settings').first().json.monthly_limit) || 3;
const rows = $('Get All Leaves').all().map(i => i.json).filter(r => r && r.request_id);
const groups = {};
for (const r of rows) {
  const month = String(r.leave_date || '').slice(0, 7);
  const key = month + '|' + r.employee_id;
  if (!groups[key]) groups[key] = { month, id: r.employee_id, name: r.employee_name, email: r.employee_email, approved: 0, dates: [], rejected: 0, auto: 0, emergency: 0, pending: 0, total: 0 };
  const g = groups[key];
  g.total += 1;
  const st = String(r.status || '');
  if (st.indexOf('Approved') === 0) {
    g.approved += Number(r.leave_days) || 0;
    g.dates.push(r.leave_date + (r.day_type === 'Half Day' ? ' (half)' : ''));
    if (st.indexOf('Emergency') >= 0) g.emergency += 1;
  } else if (st.indexOf('Rejected') >= 0) {
    g.rejected += 1;
    if (st === 'Auto-Rejected') g.auto += 1;
  } else g.pending += 1;
}
const out = Object.values(groups).sort((a, b) => b.month.localeCompare(a.month) || String(a.name).localeCompare(String(b.name)));
return out.map(g => ({ json: {
  'Month': g.month,
  'Employee ID': g.id,
  'Employee Name': g.name,
  'Employee Email': g.email,
  'Approved Days': g.approved,
  'Monthly Limit': limit,
  'Remaining Days': Math.max(limit - g.approved, 0),
  'Limit Status': g.approved > limit ? 'Over limit (emergency)' : (g.approved >= limit ? 'Limit reached' : 'Within limit'),
  'Approved Leave Dates': g.dates.sort().join(', '),
  'Rejected Requests': g.rejected,
  'Auto-Rejected': g.auto,
  'Emergency Approved': g.emergency,
  'Pending Requests': g.pending,
  'Total Requests': g.total,
} }));
